import sys

data = sys.stdin.read().split()
q = int(data[0])
out = []
for v in data[1:1 + q]:
    x = int(v)
    ans = -1
    for c in range(x // 20 + 1):
        for b in range((x - 20 * c) // 9 + 1):
            rest = x - 20 * c - 9 * b
            if rest % 6 == 0:
                n = c + b + rest // 6
                if ans == -1 or n < ans:
                    ans = n
    out.append(str(ans))
print('\n'.join(out))

